-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/otherAreas/RQ1_Rycharde_the_Chef.lua"]={["Path"]="scripts/quests/otherAreas/RQ1_Rycharde_the_Chef.lua",["SHA256"]="2c0cbe90972367a6370f73d90b739077bbcd5432efc3e6b150b6b0130221fe60",["Text"]="-----------------------------------\n-- Rycharde the Chef\n-- Variable Prefix: [4][0]\n-----------------------------------\n-- ZONE,   NPC,          POS\n-- Mhaura, Rycharde,     !pos  17.451 -16.000 88.815 249\n-- Mhaura, Take,         !pos  20.616  -8.000 69.757 249\n-- Mhaura, Numi Adaligo, !pos -80.332 -24.050 34.794 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.RYCHARDE_THE_CHEF)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.PURVEYOR_IN_TRAINING,\n    gil      = 1500,\n}\n\nquest.sections =\n{\n    -- Section: Quest available. Talk to Numi Adaligo, Take and Rycharde.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(70, xi.item.SLICE_OF_DHALMEL_MEAT)\n                    elseif quest:getVar(player, 'Prog') > 2 then\n                        return quest:progressEvent(71, xi.item.SLICE_OF_DHALMEL_MEAT)\n                    end\n                end,\n            },\n\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(60)\n                    elseif quest:getVar(player, 'Prog') > 1 then\n                        return quest:event(68)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [50] = function(player, csid, option, npc)\n                    if option == 2 then -- Ask for work.\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [60] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [70] = function(player, csid, option, npc)\n                    if option == 71 then -- Accept quest.\n                        quest:begin(player)\n                    elseif option == 70 then -- Decline quest.\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n\n                [71] = function(player, csid, option, npc)\n                    if option == 72 then  -- Accept quest.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted. Handle trade outcomes.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(72) -- Interaction dialog.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.SLICE_OF_DHALMEL_MEAT, 2 } }) then\n                        return quest:progressEvent(74) -- Quest completed dialog.\n                    elseif trade:hasItemQty(xi.item.SLICE_OF_DHALMEL_MEAT, 1)  then\n                        return quest:event(73) -- \"That's not enough!\" dialog.\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(68), -- Optional dialog.\n\n            onEventFinish =\n            {\n                [74] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Used for next quest wait time.\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ2_Way_of_the_Cook.lua"]={["Path"]="scripts/quests/otherAreas/RQ2_Way_of_the_Cook.lua",["SHA256"]="1f467414ef172ed5fd0a73493ca2c93daca303e0b3843c0a603ae278e6c30061",["Text"]="-----------------------------------\n-- Way of the Cook\n-- Variable Prefix: [4][1]\n-----------------------------------\n-- ZONE,   NPC,      POS\n-- Mhaura, Rycharde, !pos 17.451 -16.000 88.815 249\n-----------------------------------\n\nlocal quest          = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.WAY_OF_THE_COOK)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.ONE_STAR_PURVEYOR,\n}\n\nquest.sections =\n{\n    -- Section: Check if quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.RYCHARDE_THE_CHEF) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('Quest[4][0]DayCompleted') + 8 <= VanadielUniqueDay() and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 3\n                    then\n                        return quest:progressEvent(76, xi.item.BEEHIVE_CHIP, xi.item.SLICE_OF_DHALMEL_MEAT) -- Way of the Cook starting event.\n                    else\n                        return quest:event(75) -- Default dialog after completing previous quest.\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(68),\n\n            onEventFinish =\n            {\n                [76] = function(player, csid, option, npc)\n                    if option == 74 then -- Accept quest option.\n                        player:setCharVar('Quest[4][0]DayCompleted', 0) -- Delete previous quest (Rycharde the Chef) variables\n                        quest:setVar(player, 'EndTime', VanadielTime() + (3 * xi.vanaTime.DAY)) -- Set current quest started variables\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted. Handle trade and time limit\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    local currentTime = VanadielTime()\n                    local endTime     = quest:getVar(player, 'EndTime')\n\n                    if currentTime < endTime then\n                        local hoursLeft = math.ceil((endTime - currentTime) / xi.vanaTime.HOUR)\n                        return quest:event(78, hoursLeft) -- You have x hours left.\n                    else\n                        return quest:event(79) -- Not done yet.\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.SLICE_OF_DHALMEL_MEAT, xi.item.BEEHIVE_CHIP }) then\n                        local currentTime = VanadielTime()\n                        local endTime     = quest:getVar(player, 'EndTime')\n\n                        if currentTime < endTime then\n                            return quest:progressEvent(80) -- Quest completed in time.\n                        else\n                            return quest:progressEvent(81) -- Quest completed late.\n                        end\n                    elseif\n                        npcUtil.tradeHasExactly(trade, { xi.item.SLICE_OF_DHALMEL_MEAT }) or\n                        npcUtil.tradeHasExactly(trade, { xi.item.BEEHIVE_CHIP })\n                    then\n                        return quest:event(73) -- Incomplete trade.\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(65),\n\n            onEventFinish =\n            {\n                [80] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        npcUtil.giveCurrency(player, 'gil', 1500)\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Set completition day of WAY_OF_THE_COOK quest.\n                    end\n                end,\n\n                [81] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        npcUtil.giveCurrency(player, 'gil', 1000)\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Set completition day of WAY_OF_THE_COOK quest.\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ3_Unending_Chase.lua"]={["Path"]="scripts/quests/otherAreas/RQ3_Unending_Chase.lua",["SHA256"]="203a4a77a2e8836cad8a0b956fd3acbfdfdbbd7a52e77909fc0764b1bca69c7f",["Text"]="-----------------------------------\n-- Unending Chase\n-- Variable Prefix: [4][2]\n-----------------------------------\n-- ZONE,   NPC,      POS\n-- Mhaura, Rycharde, !pos 17.451 -16.000 88.815 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNENDING_CHASE)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.TWO_STAR_PURVEYOR,\n    gil      = 2100,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.WAY_OF_THE_COOK) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('Quest[4][1]DayCompleted') + 7 < VanadielUniqueDay() and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 3\n                    then\n                        if quest:getVar(player, 'Prog') == 0 then\n                            return quest:progressEvent(82, xi.item.PUFFBALL) -- Unending Chase starting event.\n                        else\n                            return quest:progressEvent(84, xi.item.PUFFBALL) -- Unending Chase starting event after rejecting it.\n                        end\n                    else\n                        return quest:event(75)\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(65),\n\n            onEventFinish =\n            {\n                [82] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:setCharVar('Quest[4][1]DayCompleted', 0)  -- Delete previous quest (Rycharde the Chef) variables\n\n                    if option == 77 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n\n                [84] = function(player, csid, option, npc)\n                    if option == 78 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(85) -- No hurry dialog.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.PUFFBALL }) then\n                        return quest:progressEvent(83) -- Quest completed.\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(65),\n\n            onEventFinish =\n            {\n                [83] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Set completition day of quest.\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ4_His_Name_is_Valgeir.lua"]={["Path"]="scripts/quests/otherAreas/RQ4_His_Name_is_Valgeir.lua",["SHA256"]="15752b5dc6159602162e7601a8e40189c8da0d62ae5480685c3519e97fbd10fd",["Text"]="-----------------------------------\n-- His Name is Valgeir\n-- Variable Prefix: [4][3]\n-----------------------------------\n-- ZONE,    NPC,      POS\n-- Mhaura,  Rycharde, !pos 17.451 -16.000 88.815 249\n-- Selbina, Valgeir,  !pos 57.496 -15.273 20.229 248\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.HIS_NAME_IS_VALGEIR)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.WINDURST,\n    gil      = 2000,\n    keyItem  = xi.keyItem.MAP_OF_THE_TORAIMARAI_CANAL,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNENDING_CHASE) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('Quest[4][2]DayCompleted') + 2 < VanadielUniqueDay() and\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 3\n                    then\n                        return quest:progressEvent(86) -- His Name is Valgeir starting event.\n                    else\n                        return quest:event(75)\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(65),\n\n            onEventFinish =\n            {\n                [86] = function(player, csid, option, npc)\n                    if option == 80 or option == 81 then -- Accept quest option.\n                        player:setCharVar('Quest[4][2]DayCompleted', 0)   -- Delete previous quest (Unending Chase) variables\n                        npcUtil.giveKeyItem(player, xi.keyItem.ARAGONEU_PIZZA) -- Give pizza to player\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Felisa'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.ARAGONEU_PIZZA) and -- No free ride after delivering Pizza.\n                        player:getZPos() > 38.5 and -- Pos check.\n                        quest:getVar(player, 'Prog') == 0 -- Hasn't taken the free ride.\n                    then\n                        return quest:progressEvent(230) -- Free ride. 1 time only. Non-Mandatory step.\n                    end\n                end,\n            },\n\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ARAGONEU_PIZZA) then\n                        return quest:progressEvent(88) -- Finish quest.\n                    else\n                        return quest:event(87) -- Not delivered the pizza yet.\n                    end\n                end,\n            },\n\n            ['Take'] = quest:event(65),\n\n            onEventFinish =\n            {\n                [88] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addExp(2000)\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Set completition day of quest.\n                    end\n                end,\n\n                [230] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ARAGONEU_PIZZA) then\n                        return quest:progressEvent(100) -- Deliver Pizza.\n                    else\n                        return quest:event(101) -- Pizza delivered.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.ARAGONEU_PIZZA)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ5_Expertise.lua"]={["Path"]="scripts/quests/otherAreas/RQ5_Expertise.lua",["SHA256"]="3d9e8e1c4e366a628cda0c03be3a07d6dba2c4c4ae18ada28cae52e5fba4aca0",["Text"]="-----------------------------------\n-- Expertise\n-- Variable Prefix: [4][4]\n-----------------------------------\n-- ZONE,    NPC,     POS\n-- Mhaura,  Take,    !pos 20.616  -8.000 69.757 249\n-- Selbina, Valgeir, !pos 57.496 -15.273 20.229 248\n-----------------------------------\nlocal mhauraID  = zones[xi.zone.MHAURA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.EXPERTISE)\n\nquest.reward =\n{\n    item  = xi.item.TABLEWARE_SET,\n    title = xi.title.THREE_STAR_PURVEYOR,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.HIS_NAME_IS_VALGEIR) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n\n            ['Rycharde'] = quest:event(89),\n\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getFameLevel(xi.fameArea.WINDURST) >= 3 and\n                        player:getCharVar('Quest[4][3]DayCompleted') + 8 < VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(61) -- Quest starting event.\n                    else\n                        return quest:event(65)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [61] = function(player, csid, option, npc)\n                    player:setCharVar('Quest[4][3]DayCompleted', 0) -- Delete Variable\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(62, xi.item.TABLEWARE_SET) -- Give dish from Valgeir.\n                    else\n                        return quest:event(63) -- Not goten the dish from Valgeir.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LAND_CRAB_BISQUE) -- Give Land Crab Bisque from Valgeir.\n                        player:messageSpecial(mhauraID.text.KEYITEM_OBTAINED + 1, xi.keyItem.LAND_CRAB_BISQUE)\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Completition day of Expertise quest.\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(102, xi.item.SCREAM_FUNGUS, xi.item.SLICE_OF_LAND_CRAB_MEAT) -- Ask for ingredients to cook.\n\n                    elseif questProgress == 1 then\n                        return quest:event(104) -- Reminder.\n\n                    elseif questProgress == 2 then\n                        local readyTime = quest:getVar(player, 'readyTime')\n\n                        if readyTime <= GetSystemTime() then -- Done waiting\n                            return quest:progressEvent(105) -- Get food.\n                        else\n                            return quest:event(141)\n                        end\n\n                    elseif questProgress == 3 then\n                        return quest:event(142)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.SCREAM_FUNGUS, xi.item.SLICE_OF_LAND_CRAB_MEAT }) then\n                        return quest:progressEvent(103) -- Give ingredients.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [103] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setVar(player, 'readyTime', GetSystemTime() + 24 * 144) -- Current time + 24 hours * 144 real seconds (Thats the ammount of seconds a Vana'Diel hour takes)\n                    player:confirmTrade()\n                end,\n\n                [105] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LAND_CRAB_BISQUE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ6_The_Clue.lua"]={["Path"]="scripts/quests/otherAreas/RQ6_The_Clue.lua",["SHA256"]="038a60504d828e75e60cfff55f1f776b10d5f27c13912261de0a914180f4bc52",["Text"]="-----------------------------------\n-- The Clue\n-- Variable Prefix: [4][5]\n-----------------------------------\n-- ZONE,   NPC,      POS\n-- Mhaura, Rycharde, !pos 17.451 -16.000 88.815 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_CLUE)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.WINDURST,\n    title    = xi.title.FOUR_STAR_PURVEYOR,\n    gil      = 3000,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available and never interacted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.EXPERTISE) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('Quest[4][4]DayCompleted') + 7 < VanadielUniqueDay() then\n                        if quest:getVar(player, 'Prog') == 0 then\n                            return quest:progressEvent(90, xi.item.CRAWLER_EGG) -- Starting event.\n                        else\n                            return quest:progressEvent(91, xi.item.CRAWLER_EGG) -- Starting event after rejecting.\n                        end\n                    end\n                end,\n            },\n\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(64) -- Default message after clompleting Expertise quest and before accepting The Clue quest.\n                end,\n            },\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:setCharVar('Quest[4][4]DayCompleted', 0)  -- Delete previous quest (Rycharde the Chef) variables\n                    if option == 83 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n\n                [91] = function(player, csid, option, npc)\n                    if option == 83 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(143)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(65)\n                end,\n            },\n\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(85) -- No hurry dialog.\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.CRAWLER_EGG, 4 } }) then\n                        return quest:progressEvent(92) -- Quest completed.\n                    else\n                        local count      = trade:getItemCount()\n                        local crawlerEgg = trade:hasItemQty(xi.item.CRAWLER_EGG, trade:getItemCount())\n\n                        if crawlerEgg and count < 4 then\n                            return quest:event(93)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [92] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        quest:setVar(player, 'DayCompleted', VanadielUniqueDay()) -- Set completition day of quest.\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(143)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/RQ7_The_Basics.lua"]={["Path"]="scripts/quests/otherAreas/RQ7_The_Basics.lua",["SHA256"]="b962856cbe2463d3e4f780e23af6e8f1dccec0ea6972fb6538281e28e7e63d5b",["Text"]="-----------------------------------\n-- The Basics\n-- Variable Prefix: [4][6]\n-----------------------------------\n-- ZONE,    NPC,      POS\n-- Mhaura,  Rycharde, !pos 17.451 -16.000 88.815 249\n-- Selbina, Valgeir,  !pos 57.496 -15.273 20.229 248\n-----------------------------------\nlocal selbinaID = zones[xi.zone.SELBINA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_BASICS)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.WINDURST,\n    item     = xi.item.TEA_SET,\n    title    = xi.title.FIVE_STAR_PURVEYOR,\n}\n\nquest.sections =\n{\n    -- Section: Quest is available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.WINDURST) >= 5 and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_CLUE) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('Quest[4][5]DayCompleted') + 7 < VanadielUniqueDay() then\n                        return quest:progressEvent(94) -- Quest starting event.\n                    end\n                end,\n            },\n\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(66)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [94] = function(player, csid, option, npc)\n                    if option == 85 then -- Accept quest option.\n                        player:setCharVar('Quest[4][5]DayCompleted', 0)  -- Delete previous quest (The clue) variables.\n                        npcUtil.giveKeyItem(player, xi.keyItem.MHAURAN_COUSCOUS) -- Give Key Item to player.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(144)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepeted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            -- TODO: Find information about the ferry free ride. NPC involved and number of times it allows for free rides.\n            -- KNOWN: It isnt mandatory to take the ferry.\n\n            ['Rycharde'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { xi.item.BAKED_POPOTO }) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(96) -- Quest completed.\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:event(95)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [96] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addExp(2000)\n                        quest:setVar(player, 'CommentaryValgeir', 1)\n                        quest:setVar(player, 'CommentaryRycharde', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(106) -- Deliver Key Item.\n                    else\n                        return quest:event(145)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [106] = function(player, csid, option, npc)\n                    npcUtil.giveItem(player, xi.item.BAKED_POPOTO)\n                    player:delKeyItem(xi.keyItem.MHAURAN_COUSCOUS)\n                    player:messageSpecial(selbinaID.text.KEYITEM_OBTAINED + 1, xi.keyItem.MHAURAN_COUSCOUS)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n    },\n\n    -- Section: Quest completed. Handle optional post quest dialogs and default interactions.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Rycharde'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'CommentaryRycharde') == 1 then\n                        return quest:event(97) -- Optional dialog.\n                    else\n                        return quest:event(98):replaceDefault() -- Default message after clompleting this quest.\n                    end\n                end,\n            },\n\n            ['Take'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(67):replaceDefault() -- Default message after clompleting this quest.\n                end,\n            },\n\n            onEventFinish =\n            {\n                [97] = function(player, csid, option, npc)\n                    quest:setVar(player, 'CommentaryRycharde', 0)\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Valgeir'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'CommentaryValgeir') == 1 then\n                        return quest:event(107) -- Optional dialog.\n                    else\n                        return quest:event(146):replaceDefault() -- Default message after clompleting this quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [107] = function(player, csid, option, npc)\n                    quest:setVar(player, 'CommentaryValgeir', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Recycling_Rods.lua"]={["Path"]="scripts/quests/otherAreas/Recycling_Rods.lua",["SHA256"]="15b58f11834f70773805f4849a9c876adca16ed6f5609ddcdde0198bfa9ba36b",["Text"]="-----------------------------------\n-- Recycling Rods\n-----------------------------------\n-- Log ID: 4, Quest ID: 30\n-- Keshab-Menjab : !pos -15.6 -8 52 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.RECYCLING_RODS)\n\nquest.reward =\n{\n    gil = 1500,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Keshab-Menjab'] = quest:progressEvent(313),\n\n            onEventFinish =\n            {\n                [313] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Keshab-Menjab'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(315)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CLEAN_SNAP_ROD) then\n                        return quest:progressEvent(317)\n                    else\n                        return quest:event(316)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [317] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Keshab-Menjab'] = quest:event(314),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Requiem_of_Sin.lua"]={["Path"]="scripts/quests/otherAreas/Requiem_of_Sin.lua",["SHA256"]="bea78ef86740f74c9265535e95e1549fd57526116892ae5c658551db59050d2e",["Text"]="-----------------------------------\n-- Requiem of Sin\n-----------------------------------\n-- Log ID: 4, Quest ID: 83\n-- Despachiaire !pos 111.209 -40.015 -85.481\n-----------------------------------\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.REQUIEM_OF_SIN)\n\nquest.reward =\n{\n    title = xi.title.DISCIPLE_OF_JUSTICE,\n}\n\nquest.sections =\n{\n    -- Section 1: Player has completed Tango with a Tracker and can receive the initial letter from Despachiaire.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TANGO_WITH_A_TRACKER)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('ShikareeBattleWait') < NextConquestTally() and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(578)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [578] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_SHIKAREE_Y)\n                    player:setCharVar('ShikareeBattleWait', NextConquestTally())\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.BONEYARD_GULLY] =\n        {\n            onEventFinish =\n            {\n                [32000] = function(player, csid, option, npc)\n                    local battlefield = player:getBattlefield()\n                    if not battlefield then\n                        return\n                    end\n\n                    if battlefield:getID() == xi.battlefield.id.REQUIEM_OF_SIN then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section 2: Player has the letter and can obtain replacement letters or enter the battlefield.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('ShikareeBattleWait') < NextConquestTally() and\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_SHIKAREE_Y)\n                    then\n                        return quest:progressEvent(579)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [579] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_SHIKAREE_Y)\n                    player:setCharVar('ShikareeBattleWait', NextConquestTally())\n                end,\n            },\n        },\n\n        [xi.zone.BONEYARD_GULLY] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.REQUIEM_OF_SIN then\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section 3: Quest is completed. Player can obtain a new Letter From the Mithran Trackers once per conquest tally\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getCharVar('ShikareeBattleWait') < NextConquestTally() and\n                not player:hasKeyItem(xi.keyItem.LETTER_FROM_THE_MITHRAN_TRACKERS)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] = quest:progressEvent(579),\n\n            onEventFinish =\n            {\n                [579] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_THE_MITHRAN_TRACKERS)\n                    player:setCharVar('ShikareeBattleWait', NextConquestTally())\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Secrets_of_Ovens_Lost.lua"]={["Path"]="scripts/quests/otherAreas/Secrets_of_Ovens_Lost.lua",["SHA256"]="774c01a24076671aa26b2ca3070f70d753245524b9ae092fb42522e39c3bf268",["Text"]="-----------------------------------\n-- Spice Gals\n-----------------------------------\n-- Log ID: 4, Quest ID: 73\n-----------------------------------\n-- Despachiaire !pos 111.209 -40.015 -85.481\n-- Jonette      !pos -70.889 -11.212 9.954\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.SECRETS_OF_OVENS_LOST)\n\nquest.reward =\n{\n    item = xi.item.MIRATETES_MEMOIRS,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return vars.Wait < NextConquestTally() and\n                vars.Prog == 0 and\n                player:hasCompletedQuest(xi.questLog.SANDORIA, xi.quest.id.sandoria.SPICE_GALS)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.SECRETS_OF_OVENS_LOST) == xi.questStatus.QUEST_AVAILABLE and\n                        quest:getVar(player, 'Option') == 0\n                    then\n                        return quest:progressEvent(505)\n                    end\n                end,\n            },\n\n            ['Jonette'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(506)\n                    elseif player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.SECRETS_OF_OVENS_LOST) == xi.questStatus.QUEST_COMPLETED then\n                        return quest:progressEvent(507) -- Repeat after conquest tally\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [505] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [506] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [507] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 1\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Jonette'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TAVNAZIAN_COOKBOOK) then\n                        return quest:progressEvent(508)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [508] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.TAVNAZIAN_COOKBOOK)\n                        quest:setVar(player, 'Wait', NextConquestTally())\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SACRARIUM] =\n        {\n            ['qm_tavnazian_cookbook'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.TAVNAZIAN_COOKBOOK) then\n                        return quest:keyItem(xi.keyItem.TAVNAZIAN_COOKBOOK)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PHOMIUNA_AQUEDUCTS] =\n        {\n            ['qm_tavnazian_cookbook'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.TAVNAZIAN_COOKBOOK) then\n                        return quest:keyItem(xi.keyItem.TAVNAZIAN_COOKBOOK)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Tango_with_a_Tracker.lua"]={["Path"]="scripts/quests/otherAreas/Tango_with_a_Tracker.lua",["SHA256"]="7e4b19a8b080f6d6969299be6f39c736fe01359f6bb6aa92509cced349252129",["Text"]="-----------------------------------\n-- Tango With a Tracker\n-----------------------------------\n-- Log ID: 4, Quest ID: 82\n-- Despachiaire !pos 111.209 -40.015 -85.481\n-- Quest begins on battlefield entrance and completes on battlefield win\n-- TODO: Verify CoP quest progression requirements to begin quest\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TANGO_WITH_A_TRACKER)\n\nquest.reward =\n{\n    gil   = 10000,\n    title = xi.title.SIN_HUNTER_HUNTER,\n}\n\nquest.sections =\n{\n    {\n        -- Section 1: Player receives key item to begin quest at battlefield\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.A_FATE_DECIDED)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(576)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [576] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_SHIKAREE_X)\n                    player:setCharVar('ShikareeBattleWait', NextConquestTally())   -- Player can only get a new letter once per conquest reset.\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.BONEYARD_GULLY] =\n        {\n            onEventFinish =\n            {\n                [32000] = function(player, csid, option, npc)\n                    local battlefield = player:getBattlefield()\n                    if not battlefield then\n                        return\n                    end\n\n                    if battlefield:getID() == xi.battlefield.id.TANGO_WITH_A_TRACKER then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        -- Section 2: Can speak with Despachiaire to receive letter again if failed after next conquest tally\\\n        -- Complete quest on battlefield win\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getCharVar('ShikareeBattleWait') < NextConquestTally() and\n                        not player:hasKeyItem(xi.keyItem.LETTER_FROM_SHIKAREE_X)\n                    then\n                        return quest:progressEvent(577) -- Recieve a subsequent letter\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [577] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_FROM_SHIKAREE_X)\n                    player:setCharVar('ShikareeBattleWait', NextConquestTally())   -- Player can only get a new letter once per conquest reset.\n                end,\n            },\n        },\n\n        [xi.zone.BONEYARD_GULLY] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.TANGO_WITH_A_TRACKER then\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Test_My_Mettle.lua"]={["Path"]="scripts/quests/otherAreas/Test_My_Mettle.lua",["SHA256"]="1e3074deb85fef78550f349539ef3a74fb973fa8a40457b59972c4c610db77d7",["Text"]="-----------------------------------\n-- Test My Mettle\n-----------------------------------\n-- Log ID: 4, Quest ID: 25\n-- Devean : !pos 39.86 -14.56 40 248\n-- Jar    : !gotoname Jar\n-----------------------------------\nrequire('scripts/quests/otherAreas/helpers')\n-----------------------------------\nlocal selbinaID = zones[xi.zone.SELBINA]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.TEST_MY_METTLE)\n\nquest.reward = {}\n\nlocal betAmounts =\n{\n    [1] = 1000,\n    [2] = 500,\n    [3] = 250,\n    [4] = 100,\n}\n\nlocal rewardMultiplier =\n{\n    [1] = { 24, 3.0 },\n    [2] = { 36, 2.5 },\n    [3] = { 48, 2.0 },\n    [4] = { 60, 1.5 },\n    [5] = { 72, 1.2 },\n}\n\n-- Event option return is the sum of bet amount and timeframe chosen.\nlocal function getSelectedOption(option)\n    for selectedBet = 1, 4 do\n        if option > betAmounts[selectedBet] then\n            return betAmounts[selectedBet], option - betAmounts[selectedBet]\n        end\n    end\nend\n\nlocal function getRewardMultiplier(vanaHoursRemaining)\n    if vanaHoursRemaining > 72 then\n        return 1\n    end\n\n    for i = 1, #rewardMultiplier do\n        if vanaHoursRemaining <= rewardMultiplier[i][1] then\n            return rewardMultiplier[i][2]\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_ACCEPTED and\n                player:getMainLvl() >= 10 and\n                player:getRank(player:getNation()) >= 2 and\n                player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 2 and\n                quest:getVar(player, 'Repeat') <= GetSystemTime()\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Devean'] = quest:progressEvent(120, 0, xi.item.POWER_SANDALS, 0, 0, 0, xi.item.FLINT_STONE),\n\n            onEventFinish =\n            {\n                [120] = function(player, csid, option, npc)\n                    if option == 0 then\n                        return\n                    end\n\n                    local eventCancelled = bit.rshift(option, 30) == 1 and true or false\n                    if eventCancelled then\n                        return\n                    end\n\n                    local betAmount, vanaHoursRemaining = getSelectedOption(option)\n\n                    if player:getGil() >= betAmount then\n                        player:delGil(betAmount)\n\n                        -- One Vana'diel Hour is equal to 2m24s (144s)\n                        quest:setVar(player, 'Timer', GetSystemTime() + vanaHoursRemaining * 144)\n                        quest:setVar(player, 'Reward', betAmount * getRewardMultiplier(vanaHoursRemaining))\n                        quest:begin(player)\n                    else\n                        player:messageSpecial(selbinaID.text.DONT_HAVE_ENOUGH_GIL)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Devean'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.POWER_SANDALS) then\n                        local timeRemaining = quest:getVar(player, 'Timer') - GetSystemTime()\n\n                        if timeRemaining > 0 then\n                            return quest:progressEvent(122)\n                        else\n                            return quest:progressEvent(123)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local timeRemaining = quest:getVar(player, 'Timer') - GetSystemTime()\n\n                    if timeRemaining > 0 then\n                        local hoursRemaining = math.floor(timeRemaining / 144)\n\n                        return quest:event(121, xi.item.POWER_SANDALS, hoursRemaining)\n                    else\n                        if\n                            player:hasItem(xi.item.POWER_SANDALS) and\n                            quest:getVar(player, 'Option') == 0\n                        then\n                            return quest:progressEvent(125)\n                        else\n                            return quest:progressEvent(123)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [122] = function(player, csid, option, npc)\n                    local rewardedGil = quest:getVar(player, 'Reward')\n\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        npcUtil.giveCurrency(player, 'gil', rewardedGil)\n                        player:addFame(xi.fameArea.SANDORIA, 5)\n                        player:addFame(xi.fameArea.BASTOK, 5)\n                        quest:setVar(player, 'Repeat', JstMidnight())\n                    end\n                end,\n\n                [123] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delCurrentQuest(quest.areaId, quest.questId)\n                    quest:setVar(player, 'Repeat', JstMidnight())\n                end,\n\n                [125] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.DAVOI] =\n        {\n            ['Jar'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Find the Jar's default action\n\n                    if not player:hasItem(xi.item.POWER_SANDALS) then\n                        if npcUtil.giveItem(player, xi.item.POWER_SANDALS) then\n                            xi.otherAreas.helpers.TestMyMettle.moveJar(npc)\n                        end\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Call_of_the_Sea.lua"]={["Path"]="scripts/quests/otherAreas/The_Call_of_the_Sea.lua",["SHA256"]="d40787efea7bf39957cc22ee1a48c43b086f4a8257b1af92a2a27da580aa0fa2",["Text"]="-----------------------------------\n-- The Call of the Sea\n-----------------------------------\n-- Log ID: 4, Quest ID: 67\n-- Equette          !pos 1.260 -22.438 -18.161\n-- Leporaitceau     !pos 74.981 -24.835 11.786\n-- Anteurephiaux    !pos 81.063 -24.977 -2.481\n-- QM Bloody Coffin !pos 641.281 0.295 -516.568\n-----------------------------------\nlocal misareuxID = zones[xi.zone.MISAREAUX_COAST]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_CALL_OF_THE_SEA)\n\nquest.reward =\n{\n    item = xi.item.MEMENTO_MUFFLER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Anteurephiaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(172)\n                    end\n                end,\n            },\n\n            ['Equette'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(170)\n                    end\n                end,\n            },\n\n            -- This is a missable optional cutscene that can play either before or during the quest.\n            ['Leporaitceau'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(171)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [170] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [171] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [172] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Anteurephiaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(173)\n                    end\n                end,\n            },\n\n            ['Equette'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(174)\n                    end\n                end,\n            },\n\n            -- This is a missable optional cutscene that can play either before or during the quest.\n            ['Leporaitceau'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(171)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [171] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [173] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.WHISPERING_CONCH)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [174] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.MISAREAUX_COAST] =\n        {\n            ['Bloody_Coffin'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    player:setLocalVar('NMKilled', 1)\n                end,\n            },\n\n            ['qm_bloody_coffin'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n                    if\n                        progress == 2 and\n                        player:getLocalVar('NMKilled') == 1\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHISPERING_CONCH)\n                        quest:setVar(player, 'Prog', 3)\n                        return quest:noAction()\n                    elseif\n                        progress == 2 and\n                        not GetMobByID(misareuxID.mob.BLOODY_COFFIN):isSpawned()\n                    then\n                        npcUtil.popFromQM(player, npc, misareuxID.mob.BLOODY_COFFIN, { claim = true, hide = 0 })\n                        return quest:messageSpecial(misareuxID.text.FOUL_STENCH_OF_DEATH)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Gift.lua"]={["Path"]="scripts/quests/otherAreas/The_Gift.lua",["SHA256"]="c1e1921ee872984bf4d8372d65d71cb1cea03b48a748339261416b20a4d75639",["Text"]="-----------------------------------\n-- The Gift\n-----------------------------------\n-- Log ID: 4, Quest ID: 21\n-- !addquest 4 21\n-- !additem 4375\n-- Oswald  : !pos 47.119 -15.273 7.989 248\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_GIFT)\n\nquest.reward =\n{\n    item  = xi.item.SLEEP_DAGGER,\n    title = xi.title.SAVIOR_OF_LOVE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNDER_THE_SEA) == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_SAND_CHARM) >= xi.questStatus.QUEST_ACCEPTED and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] = quest:progressEvent(70, xi.item.DANCESHROOM), -- Girlfriend needs a shroom\n\n            onEventFinish =\n            {\n                [70] = function(player, csid, option, npc)\n                    if option == 50 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(71) -- They are really hard to come by\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.DANCESHROOM) then\n                        return quest:progressEvent(72, 0, xi.item.DANCESHROOM) -- You found it! Please take this reward\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [72] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_REAL_GIFT) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] = quest:progressEvent(78):replaceDefault(),\n            -- I've been all over Vana'diel, but the inn is my favorite.\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Moogles_Picnic.lua"]={["Path"]="scripts/quests/otherAreas/The_Moogles_Picnic.lua",["SHA256"]="fca958d464bbd15cde6d758715612f4c54719adda74e5a684e9fe06acdc9ee81",["Text"]="-----------------------------------\n-- The Moogle's Picnic!\n-----------------------------------\n-- Log ID: 4, Quest ID: 101\n-- Moogle : (Mog House, Home Nation)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC)\n\nquest.reward =\n{\n    title = xi.title.MOGS_EXCEPTIONALLY_KIND_MASTER,\n}\n\n-- Every Mog House zone shares one section table.\nquest.sections = {}\n\nquest.sections[1] =\n{\n    check = function(player, status, vars)\n        local bedPlacedTime = quest:getVar(player, 'bedPlacedTime')\n\n        return status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.GIVE_A_MOOGLE_A_BREAK) and\n            xi.moghouse.inMogHouseInHomeNation(player) and\n            player:getFameLevel(player:getNation()) >= 5 and\n            quest:getLocalVar(player, 'mustZone') == 0 and\n            quest:getLocalVar(player, 'questSeen') == 0 and\n            bedPlacedTime ~= 0 and\n            GetSystemTime() > bedPlacedTime + 60\n    end\n}\n\n---@type ZoneSection\nlocal questAvailable =\n{\n    ['Moogle'] =\n    {\n        onTrigger = function(player, npc)\n            return quest:progressEvent(30009, 0, 0, 0, 4, 0, xi.item.SHRIMP_LURE, xi.item.STICK_OF_SELBINA_BUTTER)\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30009] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n\n            if option == 1 then\n                quest:begin(player)\n            end\n        end,\n    },\n}\n\nquest.sections[2] =\n{\n    check = function(player, status, vars)\n        return status == xi.questStatus.QUEST_ACCEPTED\n    end\n}\n\n---@type ZoneSection\nlocal questAccepted =\n{\n    ['Moogle'] =\n    {\n        onTrade = function(player, npc, trade)\n            if npcUtil.tradeMatches(trade, { { xi.item.SHRIMP_LURE, 1 }, { xi.item.STICK_OF_SELBINA_BUTTER, 1 } }) then\n                return quest:progressEvent(30011)\n            end\n        end,\n\n        onTrigger = function(player, npc)\n            local questProgress = quest:getVar(player, 'Prog')\n            local questSeen = quest:getLocalVar(player, 'questSeen')\n\n            if questSeen ~= 0 then\n                return nil\n            end\n\n            if questProgress == 0 then\n                return quest:progressEvent(30010, 0, 0, 0, 0, 0, xi.item.SHRIMP_LURE, xi.item.STICK_OF_SELBINA_BUTTER)\n            elseif\n                questProgress == 1 and\n                quest:getVar(player, 'Timer') < GetSystemTime()\n            then\n                return quest:progressEvent(30012)\n            end\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30010] = function(player, csid, option, npc)\n            quest:setLocalVar(player, 'questSeen', 1)\n        end,\n\n        [30011] = function(player, csid, option, npc)\n            player:tradeComplete()\n            quest:setVar(player, 'Prog', 1)\n            quest:setVar(player, 'Timer', GetSystemTime() + 60)\n        end,\n\n        [30012] = function(player, csid, option, npc)\n            if quest:complete(player) then\n                player:changeContainerSize(xi.inv.MOGSAFE, 10)\n                player:changeContainerSize(xi.inv.MOGSAFE2, 10)\n            end\n        end,\n    },\n}\n\nfor _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n    quest.sections[1][zoneId] = questAvailable\n    quest.sections[2][zoneId] = questAccepted\nend\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Old_Lady.lua"]={["Path"]="scripts/quests/otherAreas/The_Old_Lady.lua",["SHA256"]="920e6d1ece5e52bd86e979ea5e89479a77d6b49ed152ed2462bd60a9714b6f63",["Text"]="-----------------------------------\n-- The Old Lady\n-----------------------------------\n-- Log ID: 4, Quest ID: 10\n-- !addquest 4 10\n-- Vera : !pos -49 -5 20 249\n-----------------------------------\n-- Mutually exclusive with Elder Memories. Cannot be started if Elder Memories has been started or completed.\n-----------------------------------\nlocal mhauraID = zones[xi.zone.MHAURA]\n-----------------------------------\n\nlocal subJobItems =\n{\n    [0] = { item = xi.item.WILD_RABBIT_TAIL,      tradeEvent = 135 },\n    [1] = { item = xi.item.CUP_OF_DHALMEL_SALIVA, tradeEvent = 136 },\n    [2] = { item = xi.item.BLOODY_ROBE,           tradeEvent = 137 },\n}\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_OLD_LADY)\n\nquest.sections =\n{\n    -- Section: Quest is available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.ELDER_MEMORIES) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Vera'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= xi.settings.main.SUBJOB_QUEST_LEVEL then\n                        return quest:progressEvent(131, xi.item.WILD_RABBIT_TAIL) -- Player is eligible for the quest.\n                    else\n                        return quest:event(133) -- Player level is too low to be offered the quest.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [131] = function(player, csid, option, npc)\n                    if option == 40 then -- Accepted quest.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Vera'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local step          = subJobItems[questProgress]\n\n                    if step and npcUtil.tradeMatches(trade, { { step.item, 1 } }) then\n                        local nextStep = subJobItems[questProgress + 1]\n\n                        if nextStep then\n                            return quest:progressEvent(step.tradeEvent, nextStep.item)\n                        else\n                            return quest:progressEvent(step.tradeEvent)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    -- Obtained from Rhapsodies of Vanadiel 1-4, allows player to skip the item collection.\n                    if player:hasKeyItem(xi.keyItem.GILGAMESHS_INTRODUCTORY_LETTER) then\n                        return quest:progressEvent(137)\n                    end\n\n                    local step = subJobItems[quest:getVar(player, 'Prog')]\n                    if step then\n                        return quest:event(132, step.item)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [135] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [136] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [137] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:unlockJob(0)\n                        player:messageSpecial(mhauraID.text.SUBJOB_UNLOCKED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Isacio'] = quest:event(99):replaceDefault(),\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Vera'] = quest:event(138):replaceDefault(),\n        },\n\n        [xi.zone.SELBINA] =\n        {\n            ['Isacio'] = quest:event(99):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Real_Gift.lua"]={["Path"]="scripts/quests/otherAreas/The_Real_Gift.lua",["SHA256"]="78219a29e724bde513d5ea41371edaa88fa0444288042d46a67c10e2e033313c",["Text"]="-----------------------------------\n-- The Real Gift\n-----------------------------------\n-- Log ID: 4, Quest ID: 22\n-- !addquest 4 22\n-- !additem 4484\n-- Oswald  : !pos 47.119 -15.273 7.989 248\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_REAL_GIFT)\n\nquest.reward =\n{\n    item  = xi.item.GLASS_FIBER_FISHING_ROD,\n    title = xi.title.THE_LOVE_DOCTOR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNDER_THE_SEA) == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_SAND_CHARM) >= xi.questStatus.QUEST_COMPLETED and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] = quest:progressEvent(73, xi.item.SHALL_SHELL), -- Bring me a shall shell\n\n            onEventFinish =\n            {\n                [73] = function(player, csid, option, npc)\n                    if option == 50 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(74, xi.item.SHALL_SHELL) -- Shall shells yield pearls\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SHALL_SHELL) then\n                        return quest:progressEvent(75) -- You're so fantastic! Thank you!\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [75] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] = quest:progressEvent(76):replaceDefault(),\n            -- Thanks for all you've done.\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Rescue.lua"]={["Path"]="scripts/quests/otherAreas/The_Rescue.lua",["SHA256"]="6e4c6b4a746cab6c09d6580d39290dbde9c5be506c5c51d0ad4ff9236d0e6815",["Text"]="-----------------------------------\n-- The Rescue\n-----------------------------------\n-- Log ID: 4, Quest ID: 23\n-- Thunder Hawk : !pos -58 -10 6 248\n-- Jail Door    : !pos 56 0.1 -23 147\n-----------------------------------\nlocal beadeauxID = zones[xi.zone.BEADEAUX]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_RESCUE)\n\nquest.reward =\n{\n    exp     = 2000,\n    gil     = 5000,\n    keyItem = xi.keyItem.MAP_OF_THE_RANGUEMONT_PASS,\n    title   = xi.title.HONORARY_CITIZEN_OF_SELBINA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            -- TODO: Fame requirement needs verification\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 1\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Thunder_Hawk'] = quest:progressEvent(80),\n\n            onEventFinish =\n            {\n                [80] = function(player, csid, option, npc)\n                    if option == 70 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Thunder_Hawk'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.TRADERS_SACK) then\n                        return quest:progressEvent(81)\n                    else\n                        return quest:event(83)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [81] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                        player:delKeyItem(xi.keyItem.TRADERS_SACK)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BEADEAUX] =\n        {\n            ['_43b'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasKeyItem(xi.keyItem.TRADERS_SACK) and\n                        npcUtil.tradeHasExactly(trade, xi.item.QUADAV_CHARM)\n                    then\n                        return quest:progressEvent(1000)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.TRADERS_SACK) then\n                        return quest:messageSpecial(beadeauxID.text.LOCKED_DOOR_QUADAV_HAS_KEY)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1000] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.TRADERS_SACK)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Thunder_Hawk'] = quest:event(82):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/The_Sand_Charm.lua"]={["Path"]="scripts/quests/otherAreas/The_Sand_Charm.lua",["SHA256"]="4dfad22a6e2b7694b748ad8bb075b6f20e48449b566b49f6ed80421b8566ef7c",["Text"]="-----------------------------------\n-- The Sand Charm\n-----------------------------------\n-- Log ID: 4, Quest ID: 8\n-- !addquest 4 8\n-- Blandine  : !pos 23 -7 41 249\n-- Zexu      : !pos 31.511 -9.001 23.496 249\n-- Celestina : !pos -37.624 -16.050 75.681 249\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_SAND_CHARM)\n\nquest.reward =\n{\n    exp      = 2000,\n    gil      = 2000,\n    keyItem  = xi.keyItem.MAP_OF_BOSTAUNIEUX_OUBLIETTE,\n    fame     = 40,\n    fameArea = xi.fameArea.WINDURST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.WINDURST) >= 2\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Blandine'] =\n            {\n                onTrigger = function(player, npc)\n                    local xPos = player:getXPos()\n                    local zPos = player:getZPos()\n\n                    -- Cutscenes won't start in the docking area. Must be on town side.\n                    if zPos <= 29 or zPos >= 38 or xPos <= 16 or xPos >= 32 then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 0 then\n                            return quest:progressEvent(125) -- I know he's out there\n                        elseif questProgress == 2 then\n                            return quest:progressEvent(124) -- Celestina doesn't want to hear it anymore\n                        end\n                    end\n                end,\n            },\n\n            ['Zexu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(123) -- Word is, pirates got 'im\n                    end\n                end,\n            },\n\n            ['Celestina'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(126, xi.item.SAND_CHARM) -- Go get back the sand charm\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [123] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [124] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [125] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [126] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Celestina'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, xi.item.SAND_CHARM) then\n                        return quest:progressEvent(127, 0, xi.item.SAND_CHARM) -- He's dead, but he'll be back soon I'm sure\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [127] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:setCharVar('BlandineDialog', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.MHAURA] =\n        {\n            ['Blandine'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCharVar('BlandineDialog') == 1 then\n                        return quest:progressEvent(128) -- I stand here and pray for sailors now\n                    else\n                        return quest:event(129):replaceDefault() -- May the sea be kind...\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [128] = function(player, csid, option, npc)\n                    player:setCharVar('BlandineDialog', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Under_the_Sea.lua"]={["Path"]="scripts/quests/otherAreas/Under_the_Sea.lua",["SHA256"]="e2ddba37e7dcc3135c45ec538210f3c55028c298ab7d82e0b2b56c7a907cc5bf",["Text"]="-----------------------------------\n-- Under the Sea\n-----------------------------------\n-- Log ID: 4, Quest ID: 17\n-- !addquest 4 17\n-- Yaya    : !pos -18.770 -2.597 -14.929 248\n-- Oswald  : !pos 47.119 -15.273 7.989 248\n-- Jimaida : !pos -17.342 -2.597 -18.766 248\n-- Zaldon  : !pos -11.810 -7.287 -6.742 248\n-- TODO: The quest is NOT supposed to appear in your log after talking to Yaya. Verify if/when it does appear.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNDER_THE_SEA)\n\nquest.reward =\n{\n    item  = xi.item.AMBER_EARRING,\n    title = xi.title.LIL_CUPID,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.SELBINA_RABAO) >= 2 and\n                xi.settings.map.FISHING_ENABLE == true\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Yaya'] = quest:progressEvent(31),\n\n            onEventFinish =\n            {\n                [31] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(32) -- Oswald is looking for his ring\n                    elseif player:hasKeyItem(xi.keyItem.ETCHED_RING) then\n                        return quest:progressEvent(37) -- You found it!\n                    end\n                end,\n            },\n\n            ['Jimaida'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(33) -- Go see Zaldon\n                    end\n                end,\n            },\n\n            ['Zaldon'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(34, xi.item.FAT_GREEDIE)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        npcUtil.tradeHasExactly(trade, xi.item.FAT_GREEDIE)\n                    then\n                        if math.randomInt(1, 100) <= 20 then\n                            return quest:progressEvent(35) -- Ring found !\n                        else\n                            return quest:event(36) -- Ring not found\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [32] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [33] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [35] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.ETCHED_RING)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [36] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                end,\n\n                [37] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 10)\n                        player:addFame(xi.fameArea.BASTOK, 10)\n                        player:delKeyItem(xi.keyItem.ETCHED_RING)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_SAND_CHARM) == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SELBINA] =\n        {\n            ['Oswald'] = quest:event(38):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Unforgiven.lua"]={["Path"]="scripts/quests/otherAreas/Unforgiven.lua",["SHA256"]="9dc7c7cc8469803e456c45d7bf76d7dd5613ff235cdfea9f621a54313241a333",["Text"]="-----------------------------------\n-- Unforgiven\n-----------------------------------\n-- Log ID: 4, Quest ID: 72\n-- Elysia        : !pos -50.410 -22.204 -41.640 26\n-- Pradiulot     : !pos -20.814 -22 8.399 26\n-- qm_unforgiven : !pos 110.291 -40.85 -53.039\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNFORGIVEN)\n\nquest.reward =\n{\n    exp     = 2000,\n    keyItem = xi.keyItem.MAP_OF_TAVNAZIA,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.COP) >= xi.mission.id.cop.AN_INVITATION_WEST\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Elysia'] = quest:progressEvent(200),\n\n            onEventFinish =\n            {\n                [200] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Elysia'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ALABASTER_HAIRPIN) then\n                        return quest:progressEvent(202)\n                    elseif quest:getVar(player, 'Prog') == 1 then\n                        return quest:event(203) -- Reminder to talk to Pradiulot\n                    else\n                        return quest:event(201) -- Reminder to find the Alabaster Hairpin\n                    end\n                end,\n            },\n\n            ['qm_unforgiven'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ALABASTER_HAIRPIN) then\n                        return quest:keyItem(xi.keyItem.ALABASTER_HAIRPIN)\n                    end\n                end,\n            },\n\n            ['Pradiulot'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(204)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.ALABASTER_HAIRPIN)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [204] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'Post', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        -- Post Quest Cutscene\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Elysia'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') == 1 then\n                        return quest:progressEvent(205)\n                    end\n                end,\n            },\n\n            ['Pradiulot'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') == 2 then\n                        return quest:progressEvent(206)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [205] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Post', 2)\n                end,\n\n                [206] = function(player, csid, option, npc)\n                    quest:cleanup(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Uninvited_Guests.lua"]={["Path"]="scripts/quests/otherAreas/Uninvited_Guests.lua",["SHA256"]="6c7d7f2bb84f321eae68686ce9fada5b3755784be6943cf6380c035c2136873f",["Text"]="-----------------------------------\n-- Uninvited Guests\n-----------------------------------\n-- Log ID: 4, Quest ID: 81\n-- Justinius    : !pos 76 -34 68\n-- Monarch Linn : !zone 31\n-----------------------------------\n\n-- TODO: Add ROE rewards\n\nlocal phase =\n{\n    WAITING_IN_VICTORY   = 0,\n    GO_TO_MONARCH_LINN   = 1,\n    RETURNING_IN_VICTORY = 2,\n    RETURNING_IN_DEFEAT  = 3,\n    WAITING_IN_DEFEAT    = 4,\n}\n\nlocal var =\n{\n    QUEST_REWARD  = 'UninvitedGuestsReward',\n    PROGRESS      = 'Prog',\n    CONQUEST_WAIT = 'Wait'\n}\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNINVITED_GUESTS)\n\n-- The reward is one item, rolled when the player reports in. Weights total 1000.\n-- The item list comes from the JP wiki. Retail rates are not published.\n-- The memoirs is the common result. The breastplate is the rarest.\n--\n-- Source: https://wiki.ffo.jp/html/3837.html\nlocal rewards =\n{\n    { dropWeight = 541, rewardID = xi.item.MIRATETES_MEMOIRS           },\n\n    -- Common.\n    { dropWeight =  25, rewardID = xi.item.PLATE_OF_BREAM_RISOTTO      },\n    { dropWeight =  25, rewardID = xi.item.SQUARE_OF_RAXA              },\n    { dropWeight =  25, rewardID = xi.item.CHUNK_OF_ALUMINUM_ORE       },\n    { dropWeight =  25, rewardID = xi.item.SERVING_OF_CRIMSON_JELLY    },\n    { dropWeight =  25, rewardID = xi.item.TAVNAZIAN_SALAD             },\n    { dropWeight =  25, rewardID = xi.item.SERVING_OF_BISON_STEAK      },\n    { dropWeight =  25, rewardID = xi.item.BOWL_OF_MUSHROOM_STEW       },\n    { dropWeight =  25, rewardID = xi.item.TIGER_EYE                   },\n    { dropWeight =  25, rewardID = xi.item.UNICORN_HORN                },\n    { dropWeight =  25, rewardID = xi.item.ARMOIRE                     },\n    { dropWeight =  25, rewardID = xi.item.MANNEQUIN_BODY              },\n    { dropWeight =  25, rewardID = xi.item.PLATE_OF_MUSHROOM_RISOTTO   },\n\n    -- Less common.\n    { dropWeight =  14, rewardID = xi.item.MANNEQUIN_HANDS             },\n    { dropWeight =  14, rewardID = xi.item.OVERSIZED_FANG              },\n    { dropWeight =  14, rewardID = xi.item.DRAGON_BONE                 },\n    { dropWeight =  14, rewardID = xi.item.ELM_LOG                     },\n    { dropWeight =  14, rewardID = xi.item.MANNEQUIN_LEGS              },\n    { dropWeight =  14, rewardID = xi.item.MANNEQUIN_FEET              },\n    { dropWeight =  14, rewardID = xi.item.CHUNK_OF_ADAMAN_ORE         },\n\n    -- Uncommon.\n    { dropWeight =   7, rewardID = xi.item.BEHEMOTH_HIDE               },\n    { dropWeight =   7, rewardID = xi.item.PIECE_OF_HABU_SKIN          },\n    { dropWeight =   7, rewardID = xi.item.CLOUD_EVOKER                },\n    { dropWeight =   7, rewardID = xi.item.MANNEQUIN_HEAD              },\n    { dropWeight =   7, rewardID = xi.item.CHUNK_OF_ORICHALCUM_ORE     },\n    { dropWeight =   7, rewardID = xi.item.SERVING_OF_VERMILLION_JELLY },\n\n    -- Rare.\n    { dropWeight =   2, rewardID = xi.item.LEREMIEU_SALAD              },\n    { dropWeight =   2, rewardID = xi.item.ADAMANTOISE_SHELL           },\n    { dropWeight =   2, rewardID = xi.item.PIECE_OF_ANGEL_SKIN         },\n    { dropWeight =   2, rewardID = xi.item.DRAGON_HEART                },\n    { dropWeight =   2, rewardID = xi.item.SERVING_OF_MARBLED_STEAK    },\n    { dropWeight =   2, rewardID = xi.item.PLATE_OF_SEA_SPRAY_RISOTTO  },\n    { dropWeight =   2, rewardID = xi.item.LOCK_OF_SIRENS_HAIR         },\n    { dropWeight =   2, rewardID = xi.item.PLATE_OF_WITCH_RISOTTO      },\n    { dropWeight =   2, rewardID = xi.item.BOWL_OF_WITCH_STEW          },\n\n    -- Rarest.\n    { dropWeight =   1, rewardID = xi.item.ASSAULT_BREASTPLATE         },\n}\n\n-----------------------------------\n-- Set quest in starting state.\n-----------------------------------\nlocal startQuest = function(player)\n    npcUtil.giveKeyItem(player, xi.keyItem.MONARCH_LINN_PATROL_PERMIT)\n    quest:setVar(player, var.PROGRESS, phase.GO_TO_MONARCH_LINN)\n    player:setCharVar(var.QUEST_REWARD, 0)\n    quest:begin(player)\nend\n\n-----------------------------------\n-- A player variable is used to prevent the holding of Rare/Ex item to force a recalculation.\n-----------------------------------\nlocal generateReward = function(player)\n    local totalChance = 0\n    local rewardID    = 0\n\n    for _, item in pairs(rewards) do\n        totalChance = totalChance + item.dropWeight\n    end\n\n    local roll = math.randomInt(1, totalChance)\n\n    for _, item in pairs(rewards) do\n        totalChance = totalChance - item.dropWeight\n\n        if roll > totalChance then\n            rewardID = item.rewardID\n            break\n        end\n    end\n\n    player:setCharVar(var.QUEST_REWARD, rewardID)\n\n    return rewardID\nend\n\n-----------------------------------\n-- Give item (or gil) reward to player.\n-----------------------------------\nlocal giveReward = function(player)\n    local rewardID = player:getCharVar(var.QUEST_REWARD)\n\n    if rewardID == 0 then\n        rewardID = generateReward(player)\n    end\n\n    -- Retail does not complete the quest when the reward cannot be handed over.\n    -- The player keeps the rolled reward and reports again after making room.\n    if not npcUtil.giveItem(player, rewardID) then\n        return\n    end\n\n    -- The first clear pays 10,000 gil on top of the item per JP wiki.\n    if not player:hasCompletedQuest(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.UNINVITED_GUESTS) then\n        npcUtil.giveCurrency(player, 'gil', 10000)\n    end\n\n    if quest:complete(player) then\n        quest:setVar(player, var.CONQUEST_WAIT, NextConquestTally())\n        player:setCharVar(var.QUEST_REWARD, 0)\n    end\nend\n\nquest.reward =\n{\n    title = xi.title.MONARCH_LINN_PATROL_GUARD,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_SAVAGE)\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Justinius'] = quest:progressEvent(570),\n\n            onEventFinish =\n            {\n                [570] = function(player, csid, option, npc)\n                    if option == 1 then\n                        startQuest(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return (status == xi.questStatus.QUEST_ACCEPTED) or (status == xi.questStatus.QUEST_COMPLETED)\n        end,\n\n        [xi.zone.MONARCH_LINN] =\n        {\n            -- Battlefield Win\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    quest:setVar(player, var.PROGRESS, phase.RETURNING_IN_VICTORY)\n                end,\n            },\n        },\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Justinius'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress        = quest:getVar(player, var.PROGRESS)\n                    local conquestWaitFinished = quest:getVar(player, var.CONQUEST_WAIT) < NextConquestTally()\n                    local rewardID             = player:getCharVar(var.QUEST_REWARD)\n\n                    -- Player tried the battle and either lost or warped out.\n                    if\n                        questProgress == 1 and\n                        not player:hasKeyItem(xi.keyItem.MONARCH_LINN_PATROL_PERMIT)\n                    then\n                        questProgress = phase.RETURNING_IN_DEFEAT\n                        quest:setVar(player, var.PROGRESS, questProgress)\n                    end\n\n                    -- Go to Monarch Linn.\n                    if questProgress == phase.GO_TO_MONARCH_LINN then\n                        return quest:event(571)\n\n                    -- Victory. Give reward.\n                    elseif\n                        questProgress == phase.RETURNING_IN_VICTORY or\n                        rewardID > 0\n                    then\n                        return quest:progressEvent(572)\n\n                    -- Reissue key item after victory. Player has waited for conquest tally.\n                    elseif\n                        questProgress == phase.WAITING_IN_VICTORY and\n                        conquestWaitFinished\n                    then\n                        return quest:progressEvent(573)\n\n                    -- Reissue key item after failure. Player has waited for conquest tally.\n                    elseif\n                        questProgress == phase.WAITING_IN_DEFEAT and\n                        conquestWaitFinished\n                    then\n                        return quest:progressEvent(574)\n\n                    -- Failure. Player must wait until next conquest tally.\n                    elseif\n                        questProgress == phase.RETURNING_IN_DEFEAT or\n                        questProgress == phase.WAITING_IN_DEFEAT\n                    then\n                        return quest:progressEvent(575)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                -- Victory; Wait gets set with Reward.\n                [572] = function(player, csid, option, npc)\n                    giveReward(player)\n                end,\n\n                -- Repeat quest\n                [573] = function(player, csid, option, npc)\n                    if option == 1 then\n                        startQuest(player)\n                    end\n                end,\n\n                -- Repeat quest after failure (and waiting until next conquest).\n                [574] = function(player, csid, option, npc)\n                    startQuest(player)\n                end,\n\n                -- Player has failed and must wait until conquest to retry.\n                [575] = function(player, csid, option, npc)\n                    if quest:getVar(player, var.PROGRESS) == phase.RETURNING_IN_DEFEAT then\n                        quest:setVar(player, var.CONQUEST_WAIT, NextConquestTally())\n                        quest:setVar(player, var.PROGRESS, phase.WAITING_IN_DEFEAT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/Waking_the_Beast.lua"]={["Path"]="scripts/quests/otherAreas/Waking_the_Beast.lua",["SHA256"]="f20ee48eb5af771373e65ef0a3fc300cd71edf551d12c6b8fd02e11041026bf4",["Text"]="-----------------------------------\n-- Waking the Beast\n-----------------------------------\n-- Log ID: 4, Quest ID: 32\n-- ???: !pos -179 8 254\n-----------------------------------\nrequire('scripts/globals/npc_util')\nrequire('scripts/globals/quests')\nrequire('scripts/globals/interaction/quest')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.WAKING_THE_BEAST)\n\nquest.reward =\n{\n    item = xi.item.CARBUNCLES_POLE,\n}\n\nquest.sections =\n{\n    -- check to start the quest the first time\n    {\n        check = function(player, status, vars)\n            -- condition for the starting the quest the first time\n            return (status == xi.questStatus.QUEST_AVAILABLE and\n            player:hasSpell(xi.magic.spell.IFRIT) and\n            player:hasSpell(xi.magic.spell.GARUDA) and\n            player:hasSpell(xi.magic.spell.SHIVA) and\n            player:hasSpell(xi.magic.spell.RAMUH) and\n            player:hasSpell(xi.magic.spell.LEVIATHAN) and\n            player:hasSpell(xi.magic.spell.TITAN)) or\n            -- condition for the starting the quest (after completing previously)\n            (status == xi.questStatus.QUEST_COMPLETED and\n            not player:hasKeyItem(xi.keyItem.FADED_RUBY) and\n            not player:hasKeyItem(xi.keyItem.RAINBOW_RESONATOR) and\n            quest:getVar(player, 'completedThisWeek') == 0)\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm3'] = quest:progressEvent(207),\n\n            onEventFinish =\n            {\n                [207] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.RAINBOW_RESONATOR)\n                    -- if starting for the first time then begin the quest\n                    if player:getQuestStatus(quest.areaId, quest.questId) == xi.questStatus.QUEST_AVAILABLE then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- check for completing the quest the first time or subsequent times\n    {\n        check = function(player, status, vars)\n            return (status == xi.questStatus.QUEST_ACCEPTED or\n            status == xi.questStatus.QUEST_COMPLETED) and\n            player:hasKeyItem(xi.keyItem.FADED_RUBY) and\n            quest:getVar(player, 'completedThisWeek') == 0\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm3'] = quest:progressEvent(208),\n\n            onEventFinish =\n            {\n                [208] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'completedThisWeek', 1, NextConquestTally())\n                        player:delKeyItem(xi.keyItem.FADED_RUBY)\n\n                        if quest:getVar(player, 'Option') == 0 then\n                            player:addTitle(xi.title.DISTURBER_OF_SLUMBER)\n                        else\n                            player:addTitle(xi.title.INTERRUPTER_OF_DREAMS)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return (status == xi.questStatus.QUEST_ACCEPTED or\n            status == xi.questStatus.QUEST_COMPLETED) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_FLAMES) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_FROST) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_GALES) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_STORMS) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_TIDES) and\n            player:hasKeyItem(xi.keyItem.EYE_OF_TREMORS) and\n            player:hasKeyItem(xi.keyItem.RAINBOW_RESONATOR)\n        end,\n\n        [xi.zone.FULL_MOON_FOUNTAIN] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_FULLMOON then\n                        player:delKeyItem(xi.keyItem.EYE_OF_FLAMES)\n                        player:delKeyItem(xi.keyItem.EYE_OF_FROST)\n                        player:delKeyItem(xi.keyItem.EYE_OF_GALES)\n                        player:delKeyItem(xi.keyItem.EYE_OF_STORMS)\n                        player:delKeyItem(xi.keyItem.EYE_OF_TIDES)\n                        player:delKeyItem(xi.keyItem.EYE_OF_TREMORS)\n                        player:delKeyItem(xi.keyItem.RAINBOW_RESONATOR)\n\n                        npcUtil.giveKeyItem(player, xi.keyItem.FADED_RUBY)\n\n                        if option == 0 then\n                            quest:setVar(player, 'Option', 1)\n                        else\n                            quest:setVar(player, 'Option', 0)\n                        end\n                    end\n                end,\n            }\n        }\n    },\n\n    {\n        check = function(player, status, vars)\n            return (status == xi.questStatus.QUEST_ACCEPTED or\n            status == xi.questStatus.QUEST_COMPLETED) and\n            player:hasKeyItem(xi.keyItem.RAINBOW_RESONATOR)\n        end,\n\n        [xi.zone.CLOISTER_OF_FLAMES] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_FLAMES then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_FLAMES)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CLOISTER_OF_FROST] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_FROST then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_FROST)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CLOISTER_OF_GALES] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_GALES then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_GALES)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CLOISTER_OF_STORMS] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_STORMS then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_STORMS)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CLOISTER_OF_TIDES] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_TIDES then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_TIDES)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.CLOISTER_OF_TREMORS] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.WAKING_THE_BEAST_CLOISTER_OF_TREMORS then\n                        npcUtil.giveKeyItem(player, xi.keyItem.EYE_OF_TREMORS)\n                    end\n                end,\n            }\n        }\n    }\n}\n\nreturn quest\n"},["scripts/quests/otherAreas/X_Marks_The_Spot.lua"]={["Path"]="scripts/quests/otherAreas/X_Marks_The_Spot.lua",["SHA256"]="abb68522fb784b78369ac2a8fccb0968e009b0fbe79a011ea2cd59eb4d336971",["Text"]="-----------------------------------\n-- X Marks the Spot\n-----------------------------------\n-- Log ID: 4, Quest ID: 65\n-----------------------------------\n-- CoP Mission 2-5 Ancient Vows Completed\n-----------------------------------\n-- !addmission 6 20\n-- Tavnazian Safehold       !zone 26\n-- Despachiaire             !pos 111.2090 -40.0148 -85.4810\n-- Parelbriaux              !pos 113.701 -41 42.3653\n-- Odeya                    !pos 83.3227 -34.25 -70.0384\n-- Phomiuna Aqueducts       !zone 27\n-- Hidden Hallway 2nd Gate  !pos 138.1027 -24 60.3209\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.X_MARKS_THE_SPOT)\n\nquest.reward =\n{\n    gil = 4000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.COP) >= xi.mission.id.cop.ANCIENT_VOWS\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Despachiaire'] = quest:progressEvent(144),\n\n            onEventFinish =\n            {\n                [144] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            -- Will repeat until the quest is completed.\n            ['Despachiaire'] = quest:event(144):importantOnce(),\n\n            ['Parelbriaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') <= 1 then\n                        return quest:progressEvent(145)\n                    end\n                end,\n            },\n\n            ['Odeya'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if progress == 1 then\n                        return quest:progressEvent(141, 0, xi.item.TAVNAZIAN_LIVER)\n                    elseif progress == 2 then\n                        return quest:event(146, 0, xi.item.TAVNAZIAN_LIVER)\n                    elseif progress == 3 then\n                        return quest:event(147)\n                    elseif progress == 4 then\n                        return quest:progressEvent(143)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeHasExactly(trade, xi.item.TAVNAZIAN_LIVER)\n                    then\n                        return quest:progressEvent(142)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [141] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [142] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [143] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'Post', 1)\n                    end\n                end,\n\n                [145] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.PHOMIUNA_AQUEDUCTS] =\n        {\n            ['_0r9'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(37)\n                    else\n                        return\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n\n        }\n    },\n\n    {\n        -- Post Quest Dialogue, once the player gets this dialogue it will continue until the player zones.\n        -- After zoning this is never seen again.\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.TAVNAZIAN_SAFEHOLD] =\n        {\n            ['Odeya'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Post') >= 1 then\n                        return quest:event(148)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [148] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Post', 2)\n                end,\n            },\n\n            onZoneOut = function(player)\n                if quest:getVar(player, 'Post') == 2 then\n                    quest:cleanup(player)\n                end\n            end,\n        },\n    },\n}\n\nreturn quest\n"}};
